#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

static struct Node *list_from_array(const int values[], size_t count)
{
    struct Node *head = NULL;
    struct Node **tail = &head;

    for (size_t i = 0U; i < count; ++i) {
        struct Node *node = malloc(sizeof *node);
        if (node == NULL) {
            while (head != NULL) {
                struct Node *next = head->next;
                free(head);
                head = next;
            }
            return NULL;
        }
        node->value = values[i];
        node->next = NULL;
        *tail = node;
        tail = &node->next;
    }
    return head;
}

static void free_list(struct Node *head)
{
    while (head != NULL) {
        struct Node *next = head->next;
        free(head);
        head = next;
    }
}

static bool list_get(const struct Node *head, size_t index,
                     int *out, size_t *visits)
{
    *visits = 0U;
    while (head != NULL && index > 0U) {
        head = head->next;
        --index;
        ++(*visits);
    }
    if (head == NULL) return false;

    ++(*visits);
    *out = head->value;
    return true;
}

int main(void)
{
    const int values[] = { 12, 24, 36, 48, 60, 72 };
    const size_t count = sizeof values / sizeof values[0];
    const size_t index = 4U;
    struct Node *head = list_from_array(values, count);
    int list_value = 0;
    size_t visits = 0U;

    if (head == NULL) {
        puts("Could not allocate linked list");
        return EXIT_FAILURE;
    }

    printf("Array index %zu: %d (one indexed access)\n",
           index, values[index]);
    if (list_get(head, index, &list_value, &visits)) {
        printf("List index %zu: %d (%zu node visits)\n",
               index, list_value, visits);
    } else {
        puts("List index is out of range");
        free_list(head);
        return EXIT_FAILURE;
    }

    free_list(head);
    return EXIT_SUCCESS;
}

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#define QUEUE_CAPACITY 5U

struct Queue {
    int items[QUEUE_CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
};

static void queue_init(struct Queue *queue)
{
    queue->head = 0U;
    queue->tail = 0U;
    queue->count = 0U;
}

static bool enqueue(struct Queue *queue, int value)
{
    if (queue->count == QUEUE_CAPACITY) return false;

    queue->items[queue->tail] = value;
    queue->tail = (queue->tail + 1U) % QUEUE_CAPACITY;
    ++queue->count;
    return true;
}

static bool dequeue(struct Queue *queue, int *value)
{
    if (queue->count == 0U || value == NULL) return false;

    *value = queue->items[queue->head];
    queue->head = (queue->head + 1U) % QUEUE_CAPACITY;
    --queue->count;
    return true;
}

int main(void)
{
    struct Queue tasks;
    int next_task = 0;

    queue_init(&tasks);
    if (!enqueue(&tasks, 101) || !enqueue(&tasks, 102) ||
        !enqueue(&tasks, 103)) {
        puts("Initial enqueue failed");
        return 1;
    }

    if (dequeue(&tasks, &next_task)) {
        printf("Processed task: %d\n", next_task);
    }

    if (!enqueue(&tasks, 104) || !enqueue(&tasks, 105) ||
        !enqueue(&tasks, 106)) {
        puts("Queue is full");
        return 1;
    }

    while (dequeue(&tasks, &next_task)) {
        printf("Processed task: %d\n", next_task);
    }

    if (!dequeue(&tasks, &next_task)) {
        puts("Queue is empty");
    }
    return 0;
}
